    #[cfg(unix)]
    #[test]
    fn truncated_unpublished_receipt_staging_is_removed_before_retry() {
        let receipt_name = "inrou-restart-wave-1.json";
        let complete = format!(
            r#"{{"schema":"{LOCAL_RECEIPT_SCHEMA_V1}","authorization_sha256":"00","authorization_nonce":"nonce","receipt_name":"{receipt_name}","report":{{"status":"ok"}}}}"#
        );
        assert!(is_exact_local_receipt_envelope(
            complete.as_bytes(),
            "00",
            "nonce",
            receipt_name,
        ));

        let truncated = complete
            .strip_suffix('}')
            .expect("fixture has an outer envelope terminator");
        assert_eq!(truncated.as_bytes().last(), Some(&b'}'));
        assert!(
            !is_exact_local_receipt_envelope(truncated.as_bytes(), "00", "nonce", receipt_name,),
            "a nested report terminator must not prove a complete staged envelope"
        );

        let target_dir = fs::canonicalize(
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../..")
                .join("target"),
        )
        .expect("canonical workspace target directory");
        let directory = tempfile::Builder::new()
            .prefix("taira-truncated-local-receipt-")
            .tempdir_in(target_dir)
            .expect("owner-private temporary receipt root");
        let receipt_root = directory.path().to_path_buf();
        fs::set_permissions(&receipt_root, fs::Permissions::from_mode(0o700))
            .expect("protect temporary receipt root");
        validate_owner_private_dir(&receipt_root, "local receipt directory")
            .expect("owner-private receipt root");
        let staging = receipt_root.join(format!(".{receipt_name}.next"));
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .mode(0o600)
            .open(&staging)
            .expect("truncated receipt staging");
        file.write_all(truncated.as_bytes())
            .expect("write truncated staging");
        file.sync_all().expect("sync truncated staging");
        drop(file);

        reconcile_local_receipt_staging_at(&receipt_root, "00", "nonce", receipt_name)
            .expect("provably truncated unpublished staging is discarded");
        assert!(!staging.exists());
        assert!(!receipt_root.join(receipt_name).exists());

        publish_private_noreplace(&receipt_root, receipt_name, complete.as_bytes())
            .expect("retry publishes the complete receipt");
        reconcile_local_receipt_staging_at(&receipt_root, "00", "nonce", receipt_name)
            .expect("published receipt reopens cleanly");
        assert_eq!(
            fs::read(receipt_root.join(receipt_name)).expect("published receipt"),
            complete.as_bytes()
        );
    }

    #[cfg(unix)]
    #[test]
    fn complete_wrong_binding_receipt_staging_is_preserved() {
        let receipt_name = "inrou-restart-wave-1.json";
        let wrong_binding = format!(
            r#"{{"schema":"{LOCAL_RECEIPT_SCHEMA_V1}","authorization_sha256":"11","authorization_nonce":"nonce","receipt_name":"{receipt_name}","report":{{"status":"ok"}}}}"#
        );
        let target_dir = fs::canonicalize(
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../..")
                .join("target"),
        )
        .expect("canonical workspace target directory");
        let directory = tempfile::Builder::new()
            .prefix("taira-wrong-binding-local-receipt-")
            .tempdir_in(target_dir)
            .expect("owner-private temporary receipt root");
        let receipt_root = directory.path().to_path_buf();
        fs::set_permissions(&receipt_root, fs::Permissions::from_mode(0o700))
            .expect("protect temporary receipt root");
        validate_owner_private_dir(&receipt_root, "local receipt directory")
            .expect("owner-private receipt root");
        let staging = receipt_root.join(format!(".{receipt_name}.next"));
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .mode(0o600)
            .open(&staging)
            .expect("wrong-binding receipt staging");
        file.write_all(wrong_binding.as_bytes())
            .expect("write wrong-binding staging");
        file.sync_all().expect("sync wrong-binding staging");
        drop(file);

        let error = reconcile_local_receipt_staging_at(&receipt_root, "00", "nonce", receipt_name)
            .expect_err("complete wrong-binding staging must fail closed");
        assert!(
            error
                .downcast_ref::<InvalidLocalReceiptEvidence>()
                .is_some(),
            "wrong binding must be permanent invalid evidence: {error:#}"
        );
        assert_eq!(
            fs::read(&staging).expect("preserved wrong-binding staging"),
            wrong_binding.as_bytes()
        );
        let destination = receipt_root.join(receipt_name);
        assert!(!destination.exists());

        let published = format!(
            r#"{{"schema":"{LOCAL_RECEIPT_SCHEMA_V1}","authorization_sha256":"00","authorization_nonce":"nonce","receipt_name":"{receipt_name}","report":{{"status":"ok"}}}}"#
        );
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .mode(0o600)
            .open(&destination)
            .expect("published receipt fixture");
        file.write_all(published.as_bytes())
            .expect("write published receipt fixture");
        file.sync_all().expect("sync published receipt fixture");
        drop(file);
        let _error = reconcile_local_receipt_staging_at(&receipt_root, "00", "nonce", receipt_name)
            .expect_err("a published receipt must not erase conflicting staged evidence");
        assert_eq!(
            fs::read(&staging).expect("preserved staged evidence after destination conflict"),
            wrong_binding.as_bytes()
        );
        assert_eq!(
            fs::read(destination).expect("preserved published receipt"),
            published.as_bytes()
        );
    }

    #[test]
    fn cleanup_tombstones_use_one_exact_first_release_name() {
        let upload = OsString::from("a".repeat(32));
        let upload_tombstone =
            cleanup_tombstone_name(&upload, "upload").expect("canonical upload tombstone");
        assert_eq!(
            cleanup_original_name_from_tombstone(&upload_tombstone, "upload")
                .expect("parse upload tombstone"),
            Some(upload)
        );

        let inrou_stage = OsString::from("b".repeat(32));
        let inrou_stage_tombstone = cleanup_tombstone_name(&inrou_stage, "inrou_stage")
            .expect("canonical Inrou-stage tombstone");
        assert_eq!(
            cleanup_original_name_from_tombstone(&inrou_stage_tombstone, "inrou_stage")
                .expect("parse Inrou-stage tombstone"),
            Some(inrou_stage)
        );

        let release = OsString::from("1".repeat(40));
        let release_tombstone =
            cleanup_tombstone_name(&release, "release").expect("canonical release tombstone");
        assert_eq!(
            cleanup_original_name_from_tombstone(&release_tombstone, "release")
                .expect("parse release tombstone"),
            Some(release)
        );

        assert!(
            cleanup_original_name_from_tombstone(OsStr::new("ordinary-release"), "release")
                .expect("ordinary entry is not a tombstone")
                .is_none()
        );
        assert!(
            cleanup_original_name_from_tombstone(
                OsStr::new(".public-reset-cleanup-v1-short.tombstone"),
                "upload",
            )
            .is_err()
        );
        assert!(
            cleanup_tombstone_name(OsStr::new("A2345678901234567890123456789012"), "upload")
                .is_err()
        );
        #[cfg(unix)]
        {
            use std::os::unix::ffi::OsStringExt as _;

            let mut reserved_bytes = CLEANUP_TOMBSTONE_PREFIX.as_bytes().to_vec();
            reserved_bytes.push(0xff);
            assert!(
                cleanup_original_name_from_tombstone(
                    &OsString::from_vec(reserved_bytes),
                    "upload",
                )
                .is_err()
            );
            assert!(
                cleanup_original_name_from_tombstone(
                    &OsString::from_vec(vec![b'o', b't', b'h', b'e', b'r', 0xff]),
                    "upload",
                )
                .expect("non-reserved non-UTF-8 entry remains foreign")
                .is_none()
            );
        }
    }

    #[test]
    fn cleanup_plan_binds_retry_evidence_and_signed_cap() {
        let admitted = progress_admission();
        let original_name = admitted.inventory.authorization_nonce.clone();
        let marker = GeneratedMarkerV1 {
            schema: GENERATED_MARKER_SCHEMA_V1.to_owned(),
            kind: "upload".to_owned(),
            host_slug: admitted.target.slug().to_owned(),
            inventory_sha256: admitted.inventory_sha256.clone(),
            authorization_nonce: original_name.clone(),
            revision: admitted.inventory.revision.commit.clone(),
            created_at_unix_ms: 1,
        };
        let marker_sha256 = sha256_hex(json::to_json(&marker).expect("marker JSON").as_bytes());
        let entry = CleanupPlanEntryV1 {
            kind: "upload".to_owned(),
            original_name: original_name.clone(),
            original_path: Path::new(&admitted.guard.upload_parent)
                .join(&original_name)
                .to_string_lossy()
                .into_owned(),
            marker,
            marker_sha256,
            directory_device: 1,
            directory_inode: 1,
            initial_bytes: 1,
        };
        let plan = CleanupPlanV1 {
            schema: CLEANUP_PLAN_SCHEMA_V1.to_owned(),
            action: HostAction::Cleanup.label().to_owned(),
            host_slug: admitted.target.slug().to_owned(),
            request_sha256: admitted.request_sha256.clone(),
            inventory_sha256: admitted.inventory_sha256.clone(),
            authorization_sha256: admitted.authorization_sha256.clone(),
            authorization_nonce: admitted.inventory.authorization_nonce.clone(),
            max_reclaim_bytes: physical_host_cleanup_reclaim_limit(&admitted)
                .expect("physical-host cleanup partition"),
            bytes_before: 1,
            entries: vec![entry],
        };
        validate_cleanup_plan(&admitted, &plan).expect("exact cleanup plan");
        assert_eq!(
            cleanup_plan_detail(&plan),
            format!(
                "removed marker-authorized paths: {}",
                plan.entries[0].original_path
            )
        );

        let mut wrong_request = plan.clone();
        wrong_request.request_sha256 = "0".repeat(64);
        let _error = validate_cleanup_plan(&admitted, &wrong_request)
            .expect_err("another request cannot replay the plan");

        let mut duplicate = plan.clone();
        duplicate.entries.push(duplicate.entries[0].clone());
        duplicate.bytes_before = 2;
        let _error = validate_cleanup_plan(&admitted, &duplicate)
            .expect_err("duplicate cleanup roots are not canonical");

        let mut oversized = plan;
        oversized.entries[0].initial_bytes = oversized.max_reclaim_bytes + 1;
        oversized.bytes_before = oversized.entries[0].initial_bytes;
        let _error = validate_cleanup_plan(&admitted, &oversized)
            .expect_err("cleanup plan cannot exceed the signed cap");
    }

    #[test]
    fn cleanup_reclaim_limit_partitions_the_physical_host_cap_once() {
        let max_reclaim_bytes_per_host = 16 * 1024 * 1024 * 1024 + 4;
        let mut admitted = progress_admission();
        admitted.inventory.cleanup.max_reclaim_bytes_per_host = max_reclaim_bytes_per_host;
        let mut target_slugs = admitted
            .inventory
            .validators
            .iter()
            .map(|validator| validator.slug.clone())
            .collect::<Vec<_>>();
        target_slugs.push(admitted.inventory.edge.slug.clone());
        let limits = target_slugs
            .iter()
            .map(|slug| {
                select_target(&mut admitted, slug);
                physical_host_cleanup_reclaim_limit(&admitted)
                    .expect("canonical partition within the selected physical host")
            })
            .collect::<Vec<_>>();
        assert_eq!(limits.len(), 5);
        assert_eq!(
            limits[..4].iter().copied().sum::<u64>(),
            max_reclaim_bytes_per_host
        );
        assert!(
            limits[..4]
                .iter()
                .all(|limit| *limit == max_reclaim_bytes_per_host / 4)
        );
        assert_eq!(limits[4], max_reclaim_bytes_per_host);
        assert_eq!(
            limits.iter().copied().sum::<u64>(),
            2 * max_reclaim_bytes_per_host
        );

        let original_name = admitted.inventory.authorization_nonce.clone();
        let marker = GeneratedMarkerV1 {
            schema: GENERATED_MARKER_SCHEMA_V1.to_owned(),
            kind: "upload".to_owned(),
            host_slug: admitted.target.slug().to_owned(),
            inventory_sha256: admitted.inventory_sha256.clone(),
            authorization_nonce: original_name.clone(),
            revision: admitted.inventory.revision.commit.clone(),
            created_at_unix_ms: 1,
        };
        let marker_sha256 = sha256_hex(json::to_json(&marker).expect("marker JSON").as_bytes());
        let plan = CleanupPlanV1 {
            schema: CLEANUP_PLAN_SCHEMA_V1.to_owned(),
            action: HostAction::Cleanup.label().to_owned(),
            host_slug: admitted.target.slug().to_owned(),
            request_sha256: admitted.request_sha256.clone(),
            inventory_sha256: admitted.inventory_sha256.clone(),
            authorization_sha256: admitted.authorization_sha256.clone(),
            authorization_nonce: admitted.inventory.authorization_nonce.clone(),
            max_reclaim_bytes: limits[4],
            bytes_before: limits[4],
            entries: vec![CleanupPlanEntryV1 {
                kind: "upload".to_owned(),
                original_name: original_name.clone(),
                original_path: Path::new(&admitted.guard.upload_parent)
                    .join(&original_name)
                    .to_string_lossy()
                    .into_owned(),
                marker,
                marker_sha256,
                directory_device: 1,
                directory_inode: 1,
                initial_bytes: limits[4],
            }],
        };
        validate_cleanup_plan(&admitted, &plan).expect("one target may consume its exact share");
        let mut over_partition = plan;
        over_partition.entries[0].initial_bytes = over_partition.max_reclaim_bytes + 1;
        over_partition.bytes_before = over_partition.entries[0].initial_bytes;
        let _error = validate_cleanup_plan(&admitted, &over_partition)
            .expect_err("one target cannot consume one byte beyond its physical-host share");

        assert!(partition_cleanup_reclaim_limit(1, 5, 5).is_err());
        assert!(partition_cleanup_reclaim_limit(1, 0, 0).is_err());
    }

    #[test]
    fn cleanup_plan_binds_only_older_noncurrent_inrou_stages() {
        let mut admitted = progress_admission();
        admitted.authorization.claims.issued_at_unix_ms = 10;
        let old_nonce = "o".repeat(32);
        let carrier = inrou_stage_carrier(
            &admitted.inventory,
            &admitted.target.endpoint().host_identity_sha256,
        )
        .expect("fixture stage carrier");
        let marker = GeneratedMarkerV1 {
            schema: GENERATED_MARKER_SCHEMA_V1.to_owned(),
            kind: "inrou_stage".to_owned(),
            host_slug: carrier.slug.clone(),
            inventory_sha256: "1".repeat(64),
            authorization_nonce: old_nonce.clone(),
            revision: "2".repeat(40),
            created_at_unix_ms: 9,
        };
        let marker_sha256 = sha256_hex(json::to_json(&marker).expect("marker JSON").as_bytes());
        let entry = CleanupPlanEntryV1 {
            kind: "inrou_stage".to_owned(),
            original_name: old_nonce.clone(),
            original_path: inrou_stage_cleanup_parent_path(&admitted)
                .expect("fixed Inrou stage parent")
                .join(&old_nonce)
                .to_string_lossy()
                .into_owned(),
            marker,
            marker_sha256,
            directory_device: 1,
            directory_inode: 1,
            initial_bytes: 1,
        };
        let plan = CleanupPlanV1 {
            schema: CLEANUP_PLAN_SCHEMA_V1.to_owned(),
            action: HostAction::Cleanup.label().to_owned(),
            host_slug: admitted.target.slug().to_owned(),
            request_sha256: admitted.request_sha256.clone(),
            inventory_sha256: admitted.inventory_sha256.clone(),
            authorization_sha256: admitted.authorization_sha256.clone(),
            authorization_nonce: admitted.inventory.authorization_nonce.clone(),
            max_reclaim_bytes: physical_host_cleanup_reclaim_limit(&admitted)
                .expect("physical-host cleanup partition"),
            bytes_before: 1,
            entries: vec![entry],
        };
        validate_cleanup_plan(&admitted, &plan)
            .expect("older marker-bound Inrou stage is reclaimable");

        let mut current = plan.clone();
        current.entries[0].original_name = admitted.inventory.authorization_nonce.clone();
        current.entries[0].original_path = current_inrou_stage_path(&admitted)
            .expect("current stage path")
            .to_string_lossy()
            .into_owned();
        current.entries[0].marker.authorization_nonce =
            admitted.inventory.authorization_nonce.clone();
        current.entries[0].marker_sha256 = sha256_hex(
            json::to_json(&current.entries[0].marker)
                .expect("current marker JSON")
                .as_bytes(),
        );
        let _ = validate_cleanup_plan(&admitted, &current)
            .expect_err("current Inrou stage must never enter a cleanup plan");

        let mut not_older = plan;
        not_older.entries[0].marker.created_at_unix_ms = 10;
        not_older.entries[0].marker_sha256 = sha256_hex(
            json::to_json(&not_older.entries[0].marker)
                .expect("nonterminal marker JSON")
                .as_bytes(),
        );
        let _ = validate_cleanup_plan(&admitted, &not_older)
            .expect_err("a non-older Inrou stage is not proven superseded");
    }

    #[test]
    fn cleanup_plan_accounts_only_tombstone_or_completed_prefixes() {
        assert_eq!(
            cleanup_plan_deleted_prefix(100, 100, false).expect("unchanged candidate"),
            0
        );
        let _error = cleanup_plan_deleted_prefix(100, 99, false)
            .expect_err("an unrenamed candidate cannot be partially deleted");
        assert_eq!(
            cleanup_plan_deleted_prefix(100, 40, true).expect("partial tombstone"),
            60
        );
        assert_eq!(
            cleanup_plan_deleted_prefix(100, 0, true).expect("durably completed root"),
            100
        );
        let _error = cleanup_plan_deleted_prefix(100, 101, true)
            .expect_err("a planned root cannot grow past its admitted byte closure");
    }

    #[test]
    fn cleanup_plan_rechecks_the_selected_release_before_mutation() {
        let planned =
            Path::new("/srv/taira/node/releases/1111111111111111111111111111111111111111");
        let other = Path::new("/srv/taira/node/releases/2222222222222222222222222222222222222222");
        ensure_cleanup_plan_entry_not_selected("release", planned, other)
            .expect("an unselected old release remains eligible");
        let _error = ensure_cleanup_plan_entry_not_selected("release", planned, planned)
            .expect_err("a release selected after planning must never be deleted");
        ensure_cleanup_plan_entry_not_selected("upload", planned, planned)
            .expect("the release selector does not govern upload roots");
        ensure_cleanup_stage_not_current("inrou_stage", planned, other)
            .expect("an older Inrou stage remains eligible");
        let _ = ensure_cleanup_stage_not_current("inrou_stage", planned, planned)
            .expect_err("the current Inrou stage must never be deleted");
    }

    fn current_convergence_wave_fixture(
        height: u64,
    ) -> (
        InventoryV1,
        iroha_genesis::ValidatedGenesisBundle,
        norito::json::Value,
    ) {
        let (genesis, peers, evidence) =
            crate::taira_dataspace_deploy::VerifiedCommittedHeightV1::convergence_evidence_fixture(
                height,
            );
        let mut inventory = progress_admission().inventory;
        inventory.next_genesis_hash = genesis.expected_hash().to_string();
        for ((validator, client), peer) in inventory
            .validators
            .iter_mut()
            .zip(&mut inventory.validator_clients)
            .zip(peers)
        {
            validator.node_fingerprint = peer.node_fingerprint.to_string();
            validator.build_fingerprint = peer.build_fingerprint.to_string();
            validator.config_fingerprint = peer.config_fingerprint.to_string();
            client.probe_origin = peer.torii_origin;
            client.peer_id = peer.peer_id.to_string();
        }
        let wave = norito::json!({"schema": "iroha.taira.public-reset.convergence-wave.v1", "wave": 0,
            "height": height, "block_hash": (evidence.get("block_hash").unwrap().clone()), "evidence": evidence});
        (inventory, genesis, wave)
    }

    #[test]
    fn public_reset_convergence_waits_for_first_commit_without_accepting_pending_proof() {
        let (inventory, genesis, mut wave) = current_convergence_wave_fixture(1);
        validate_convergence_wave(&wave, 0, &inventory, &genesis)
            .expect("four challenged genesis tips");
        *wave.pointer_mut("/evidence/committed_height").unwrap() = norito::json::Value::from(0_u64);
        assert!(validate_convergence_wave(&wave, 0, &inventory, &genesis).is_err());
        assert!(
            validate_convergence_wave(
                &norito::json!({"committed_height": 1}),
                0,
                &inventory,
                &genesis
            )
            .is_err(),
            "unsigned current status can never authorize readiness"
        );
    }

    #[test]
    fn public_reset_convergence_rejects_fatal_identity_during_startup() {
        let (inventory, genesis, wave) = current_convergence_wave_fixture(1);
        for field in [
            "node_fingerprint",
            "build_fingerprint",
            "config_fingerprint",
        ] {
            let mut changed = wave.clone();
            *changed
                .pointer_mut(&format!("/evidence/peers/0/before/body/{field}"))
                .unwrap() = norito::json::to_value(&Hash::new(b"foreign identity")).unwrap();
            assert!(
                validate_convergence_wave(&changed, 0, &inventory, &genesis).is_err(),
                "{field}"
            );
        }
    }

    #[test]
    fn public_reset_convergence_deadline_reports_last_public_progress() {
        let inventory = progress_admission().inventory;
        let observations = vec!["awaiting challenged finality".to_owned(); 4];
        let error = convergence_deadline_error(&inventory.validators, &observations).to_string();
        for validator in inventory.validators {
            assert!(error.contains(&validator.slug));
        }
        assert!(error.contains("awaiting challenged finality"));
    }

    #[test]
    fn public_reset_convergence_waits_for_applied_successor_before_canary() {
        let (inventory, genesis, mut wave) = current_convergence_wave_fixture(2);
        *wave
            .pointer_mut("/evidence/peers/0/after/body/status/applied_height")
            .unwrap() = norito::json::Value::from(1_u64);
        assert!(
            validate_convergence_wave(&wave, 0, &inventory, &genesis).is_err(),
            "unapplied tip cannot authorize canary"
        );
        assert!(
            require_successor_checkpoint(Some(&(2, "same".into())), &(2, "same".into())).is_err()
        );
        require_successor_checkpoint(Some(&(2, "old".into())), &(3, "next".into())).unwrap();
    }

    #[test]
    fn public_reset_convergence_accepts_same_decision_across_certificate_rounds() {
        let (inventory, genesis, wave) = current_convergence_wave_fixture(2);
        let peers = wave.pointer("/evidence/peers").unwrap().as_array().unwrap();
        assert_ne!(
            peers[0].pointer("/before/body/finality_proof/block_wire"),
            peers[1].pointer("/before/body/finality_proof/block_wire"),
            "fixture uses different valid QC witnesses"
        );
        let checkpoint = validate_convergence_wave(&wave, 0, &inventory, &genesis).unwrap();
        assert_eq!(checkpoint.0, 2);
        let mut noncanonical = wave;
        *noncanonical.pointer_mut("/block_hash").unwrap() = norito::json::Value::from(checkpoint.1);
        assert!(
            validate_convergence_wave(&noncanonical, 0, &inventory, &genesis).is_err(),
            "human display hashes are not canonical JSON hash literals"
        );
    }

    #[test]
    fn public_reset_convergence_rejects_changed_execution_or_subject_at_same_height() {
        let (inventory, genesis, wave) = current_convergence_wave_fixture(2);
        for path in [
            "/block_hash",
            "/evidence/block_hash",
            "/evidence/peers/0/after/body/genesis_block_hash",
        ] {
            let mut changed = wave.clone();
            *changed.pointer_mut(path).unwrap() =
                norito::json::to_value(&Hash::new(b"different decision")).unwrap();
            assert!(
                validate_convergence_wave(&changed, 0, &inventory, &genesis).is_err(),
                "{path}"
            );
        }
    }

    #[test]
    fn public_reset_convergence_rejects_omitted_nullable_status_fields() {
        let (inventory, genesis, wave) = current_convergence_wave_fixture(2);
        for field in ["leader", "proxy_tail", "high_qc_view", "signer", "halted"] {
            let mut changed = wave.clone();
            changed
                .pointer_mut("/evidence/peers/0/before/body/status")
                .unwrap()
                .as_object_mut()
                .unwrap()
                .remove(field);
            assert!(
                validate_convergence_wave(&changed, 0, &inventory, &genesis).is_err(),
                "{field}"
            );
        }
    }

    #[test]
    fn convergence_wave_receipt_rejects_unknown_first_release_fields() {
        let (inventory, genesis, mut wave) = current_convergence_wave_fixture(1);
        wave.as_object_mut()
            .unwrap()
            .insert("retired_v0".into(), norito::json::Value::Bool(true));
        let error = validate_convergence_wave(&wave, 0, &inventory, &genesis).unwrap_err();
        assert!(error.to_string().contains("retired_v0"));
    }

