    #[test]
    fn config_upload_admission_requires_owner_private_artifact_mode() {
        let admitted = progress_admission();
        let selected = artifact(admitted.target.artifacts(), "config").unwrap();
        assert_eq!(selected.mode, 0o600);
        let mut request = admitted.request.clone();
        request.artifact_role = selected.role.clone();
        request.artifact_sha256 = selected.sha256.clone();
        request.artifact_size = selected.size;
        request.artifact_mode = selected.mode;
        validate_host_artifact_request(
            &request,
            &admitted.inventory,
            &admitted.target,
            HostAction::Upload,
        )
        .unwrap();
        for mode in [0o400, 0o640, 0o644] {
            request.artifact_mode = mode;
            assert!(
                validate_host_artifact_request(
                    &request,
                    &admitted.inventory,
                    &admitted.target,
                    HostAction::Upload,
                )
                .is_err()
            );
        }
    }

    pub(super) fn progress_admission() -> HostAdmission {
        let inventory = super::super::sample_inventory_fixture();
        let inventory_bytes =
            super::super::canonical_inventory_bytes(&inventory).expect("inventory JSON");
        let inventory_sha256 = sha256_hex(&inventory_bytes);
        let claims = super::super::AuthorizationClaimsV1 {
            action: "reset_and_deploy".to_owned(),
            qualification_scope: inventory.qualification_scope,
            deployment_id: inventory.deployment_id.clone(),
            inventory_sha256: inventory_sha256.clone(),
            artifact_closure_sha256: inventory.artifact_closure_sha256.clone(),
            runtime_client_config_sha256: inventory.runtime_client_config_sha256.clone(),
            onboarding_token_sha256: inventory.onboarding_token_sha256.clone(),
            validator_client_configs_sha256: inventory.validator_client_configs_sha256.clone(),
            inrou_stage_tree_sha256: inventory.inrou_stage_tree_sha256.clone(),
            faucet_policy: inventory.faucet_policy.clone(),
            fee_intent: inventory.fee_intent.clone(),
            authorization_nonce: inventory.authorization_nonce.clone(),
            issued_at_unix_ms: 1,
            not_before_unix_ms: 1,
            expires_at_unix_ms: u64::MAX - 2,
            execution_expires_at_unix_ms: u64::MAX - 1,
        };
        let authorization = AuthorizationEnvelopeV1 {
            schema: "iroha.taira.public-reset.authorization.v1".to_owned(),
            claims,
            signature_hex: "11".repeat(64),
        };
        let target = HostTarget::Validator(inventory.validators[0].clone());
        HostAdmission {
            request: HostRequestV1 {
                schema: HOST_REQUEST_SCHEMA_V1.to_owned(),
                action: HostAction::Stage.label().to_owned(),
                recovery_only: false,
                host_slug: inventory.validators[0].slug.clone(),
                inventory_base64: BASE64.encode(&inventory_bytes),
                authorization_base64: String::new(),
                authorization_semantic_sha256: "b".repeat(64),
                trusted_key_base64: String::new(),
                trusted_key_sha256: "c".repeat(64),
                action_deadline_unix_ms: u64::MAX - 1,
                phase_checkpoints: Vec::new(),
                artifact_role: String::new(),
                artifact_sha256: String::new(),
                artifact_size: 0,
                artifact_mode: 0,
                mutation_kind: String::new(),
                mutation_phase: String::new(),
                mutation_idempotency_key: String::new(),
                mutation_operation: String::new(),
                mutation_prepared_base64: String::new(),
                mutation_prepared_sha256: String::new(),
                mutation_transaction_hash: String::new(),
                mutation_evidence_base64: String::new(),
            },
            request_sha256: "d".repeat(64),
            inventory,
            inventory_sha256,
            authorization,
            authorization_sha256: "b".repeat(64),
            target,
            guard: HostGuardV1 {
                schema: HOST_GUARD_SCHEMA_V1.to_owned(),
                host_slug: "taira-validator-1".to_owned(),
                service_root: "/srv/taira/taira-validator-1".to_owned(),
                state_root: "/var/lib/taira/taira-validator-1".to_owned(),
                trusted_key_sha256: "c".repeat(64),
                dispatcher_path: FIXED_DISPATCHER.to_owned(),
                dispatcher_sha256: "e".repeat(64),
                upload_parent: "/srv/taira/taira-validator-1/.public-reset-upload-v1".to_owned(),
            },
            action_deadline: Instant::now() + Duration::from_secs(60),
            execution_expired: false,
        }
    }

    #[test]
    fn terminal_rollback_releases_host_lease_before_expiry() {
        let admitted = progress_admission();
        let mut progress = initial_host_progress(&admitted);
        assert!(!host_progress_releasable(&progress, false));
        assert!(host_progress_releasable(&progress, true));
        progress.touched_hosts = vec!["taira-validator-1".to_owned()];
        assert!(!host_progress_releasable(&progress, false));
        assert!(!host_progress_releasable(&progress, true));

        progress.rolling_back = true;
        assert!(!host_progress_releasable(&progress, false));
        progress.rolled_back_hosts = progress.touched_hosts.clone();
        assert!(host_progress_releasable(&progress, false));

        progress.prepared_action = Some(HostActionKeyV1 {
            host_slug: "taira-validator-1".to_owned(),
            action: HostAction::Rollback.label().to_owned(),
            artifact_role: String::new(),
        });
        assert!(!host_progress_releasable(&progress, false));
        progress.prepared_action = None;
        progress.touched_hosts.push("taira-validator-1".to_owned());
        progress
            .rolled_back_hosts
            .push("taira-validator-1".to_owned());
        assert!(!host_progress_releasable(&progress, false));
    }

    #[test]
    fn native_terminal_receipt_must_complete_host_rollback() {
        let admitted = progress_admission();
        let lease = HostLeaseV1 {
            schema: LEASE_SCHEMA_V1.to_owned(),
            inventory_sha256: admitted.inventory_sha256.clone(),
            authorization_semantic_sha256: admitted.authorization_sha256.clone(),
            authorization_nonce: admitted.inventory.authorization_nonce.clone(),
            execution_expires_at_unix_ms: admitted
                .authorization
                .claims
                .execution_expires_at_unix_ms,
        };
        let touched_hosts = BTreeSet::from([
            "taira-validator-1".to_owned(),
            "taira-validator-2".to_owned(),
            "taira-validator-3".to_owned(),
            "taira-validator-4".to_owned(),
            "taira-edge".to_owned(),
        ]);
        let terminal = norito::json!({
            "schema": (super::super::JOURNAL_SCHEMA_V1),
            "qualification_scope": "core_testnet",
            "deployment_id": (admitted.inventory.deployment_id),
            "inventory_sha256": (lease.inventory_sha256.clone()),
            "authorization_sha256": (lease.authorization_semantic_sha256.clone()),
            "authorization_nonce": (lease.authorization_nonce.clone()),
            "status": "rolled_back",
            "phase": "rolled_back",
            "next_step": 5,
            "recovery_intent": (json::Value::Null),
            "touched_validators": (super::super::VALIDATOR_SLUGS.to_vec()),
            "edge_touched": true,
            "edge_rollback_complete": true,
            "rollback_next_validator": 4,
            "failure_summary": "forward apply failed",
            "rollback_failures": (Vec::<String>::new()),
        });
        assert!(terminal_rollback_receipt_matches(
            &lease,
            &touched_hosts,
            &terminal
        ));
        let mut missing_host = touched_hosts.clone();
        missing_host.remove("taira-validator-4");
        assert!(!terminal_rollback_receipt_matches(
            &lease,
            &missing_host,
            &terminal
        ));
        for (field, value) in [
            ("status", json::Value::String("rolling_back".to_owned())),
            ("authorization_sha256", json::Value::String("0".repeat(64))),
            ("recovery_intent", json::Value::String("pending".to_owned())),
            ("rollback_next_validator", json::Value::from(3_u64)),
            ("edge_rollback_complete", json::Value::Bool(false)),
            (
                "rollback_failures",
                norito::json!(["taira-validator-2 rollback failed"]),
            ),
        ] {
            let mut stale = terminal.clone();
            stale
                .as_object_mut()
                .expect("journal object")
                .insert(field.to_owned(), value);
            assert!(
                !terminal_rollback_receipt_matches(&lease, &touched_hosts, &stale),
                "unexpectedly accepted {field} drift"
            );
        }
    }

    fn select_target(admitted: &mut HostAdmission, slug: &str) {
        admitted.target = admitted
            .inventory
            .validators
            .iter()
            .find(|validator| validator.slug == slug)
            .cloned()
            .map(HostTarget::Validator)
            .or_else(|| {
                (admitted.inventory.edge.slug == slug)
                    .then(|| HostTarget::Edge(admitted.inventory.edge.clone()))
            })
            .expect("fixture target");
        admitted.request.host_slug = slug.to_owned();
    }

    #[test]
    fn inrou_preseed_plan_is_once_per_physical_validator_host() {
        let mut admitted = progress_admission();
        for (index, validator) in admitted.inventory.validators.iter_mut().enumerate() {
            validator.endpoint.host_identity_sha256 = if index < 2 {
                "a".repeat(64)
            } else {
                "b".repeat(64)
            };
        }
        select_target(&mut admitted, "taira-validator-1");
        let first_plan = host_forward_plan(&admitted);
        assert_eq!(
            first_plan
                .iter()
                .filter(|key| key.action == HostAction::InrouStageUpload.label())
                .count(),
            1
        );
        assert_eq!(
            first_plan
                .iter()
                .filter(|key| key.action == HostAction::Preseed.label())
                .count(),
            1
        );
        assert!(first_plan.iter().any(|key| {
            key.host_slug == "taira-validator-2" && key.action == HostAction::Reset.label()
        }));
        assert!(!first_plan.iter().any(|key| {
            key.host_slug == "taira-validator-3" && key.action == HostAction::Reset.label()
        }));

        select_target(&mut admitted, "taira-validator-3");
        let second_plan = host_forward_plan(&admitted);
        assert_eq!(
            second_plan
                .iter()
                .filter(|key| key.action == HostAction::InrouStageUpload.label())
                .count(),
            1
        );
        assert_eq!(
            second_plan
                .iter()
                .filter(|key| key.action == HostAction::Preseed.label())
                .count(),
            1
        );
    }

    #[test]
    fn inrou_stage_upload_manifest_reproduces_the_signed_tree() {
        let mut admitted = progress_admission();
        let paths = [
            INROU_STAGE_CONTAINER_FILE_V1,
            INROU_STAGE_BUNDLE_MANIFEST_FILE_V1,
            INROU_STAGE_GUEST_MANIFEST_FILE_V1,
            INROU_STAGE_DISCOVERY_DOCUMENT_FILE_V1,
            INROU_STAGE_DISCOVERY_MANIFEST_FILE_V1,
            INROU_STAGE_BUNDLE_PAYLOAD_FILE_V1,
            INROU_STAGE_RECEIPT_FILE_V1,
            INROU_STAGE_SERVICE_FILE_V1,
        ];
        let mut files = paths
            .into_iter()
            .enumerate()
            .map(|(index, path)| InrouStageUploadFileV1 {
                path: path.to_owned(),
                size: u64::try_from(index + 1).expect("bounded fixture size"),
                sha256: hex::encode([u8::try_from(index + 1).expect("bounded fixture byte"); 32]),
            })
            .collect::<Vec<_>>();
        files.sort_by(|left, right| left.path.cmp(&right.path));
        let fixed = files
            .iter()
            .map(|file| (file.path.as_str(), file.sha256.clone()))
            .collect::<BTreeMap<_, _>>();
        admitted
            .inventory
            .inrou_canary
            .as_mut()
            .expect("full Inrou fixture")
            .receipt_sha256 = fixed[INROU_STAGE_RECEIPT_FILE_V1].clone();
        admitted
            .inventory
            .inrou_canary
            .as_mut()
            .expect("full Inrou fixture")
            .container_sha256 = fixed[INROU_STAGE_CONTAINER_FILE_V1].clone();
        admitted
            .inventory
            .inrou_canary
            .as_mut()
            .expect("full Inrou fixture")
            .service_sha256 = fixed[INROU_STAGE_SERVICE_FILE_V1].clone();
        admitted
            .inventory
            .inrou_canary
            .as_mut()
            .expect("full Inrou fixture")
            .bundle_payload_sha256 = fixed[INROU_STAGE_BUNDLE_PAYLOAD_FILE_V1].clone();
        admitted
            .inventory
            .inrou_canary
            .as_mut()
            .expect("full Inrou fixture")
            .bundle_manifest_sha256 = fixed[INROU_STAGE_BUNDLE_MANIFEST_FILE_V1].clone();
        admitted
            .inventory
            .inrou_canary
            .as_mut()
            .expect("full Inrou fixture")
            .guest_manifest_sha256 = fixed[INROU_STAGE_GUEST_MANIFEST_FILE_V1].clone();
        admitted
            .inventory
            .inrou_canary
            .as_mut()
            .expect("full Inrou fixture")
            .discovery_document_sha256 = fixed[INROU_STAGE_DISCOVERY_DOCUMENT_FILE_V1].clone();
        admitted
            .inventory
            .inrou_canary
            .as_mut()
            .expect("full Inrou fixture")
            .discovery_manifest_sha256 = fixed[INROU_STAGE_DISCOVERY_MANIFEST_FILE_V1].clone();
        let mut tree = Sha256::new();
        tree.update(b"iroha:taira:public-reset:inrou-stage-tree:v1\0");
        let mut stage_bytes = 0_u64;
        for file in &files {
            stage_bytes += file.size;
            update_frame(&mut tree, file.path.as_bytes());
            update_frame(&mut tree, &file.size.to_be_bytes());
            update_frame(&mut tree, file.sha256.as_bytes());
        }
        let stage_tree_sha256 = hex::encode(tree.finalize());
        admitted
            .inventory
            .inrou_canary
            .as_mut()
            .expect("full Inrou fixture")
            .stage_bytes = stage_bytes;
        admitted
            .inventory
            .inrou_canary
            .as_mut()
            .expect("full Inrou fixture")
            .stage_tree_sha256 = stage_tree_sha256.clone();
        admitted.authorization.claims.inrou_stage_tree_sha256 = Some(stage_tree_sha256.clone());
        let manifest = InrouStageUploadManifestV1 {
            schema: INROU_STAGE_UPLOAD_SCHEMA_V1.to_owned(),
            stage_tree_sha256,
            stage_bytes,
            files,
        };
        validate_inrou_stage_upload_manifest(&admitted, &manifest)
            .expect("exact signed upload tree");

        let mut reordered = manifest.clone();
        reordered.files.swap(0, 1);
        let _error = validate_inrou_stage_upload_manifest(&admitted, &reordered)
            .expect_err("noncanonical file ordering must fail closed");
        let mut traversal = manifest;
        traversal.files[0].path = "../container.json".to_owned();
        let _error = validate_inrou_stage_upload_manifest(&admitted, &traversal)
            .expect_err("stage path traversal must fail closed");
    }

    #[test]
    fn host_receipt_names_cover_every_action_and_artifact_role() {
        // The same list builds the test inputs and an exhaustive enum match:
        // adding a HostAction without testing its receipt name cannot compile.
        macro_rules! all_host_actions {
            ($($variant:ident),+ $(,)?) => {{
                let actions = [$(HostAction::$variant),+];
                for action in &actions {
                    match action { $(HostAction::$variant => (),)+ }
                }
                actions
            }};
        }
        let actions = all_host_actions!(
            Preflight,
            UnitProbe,
            Upload,
            Stage,
            InrouStageUpload,
            Stop,
            Install,
            Reset,
            Preseed,
            Start,
            BeaconActivate,
            Restart,
            EdgeStage,
            EdgeCutover,
            EdgeVerify,
            Seal,
            Cleanup,
            Rollback,
            MutationReserve,
        );
        let roles = super::super::VALIDATOR_ARTIFACT_ROLES
            .iter()
            .chain(&super::super::EDGE_ARTIFACT_ROLES)
            .copied()
            .collect::<BTreeSet<_>>();
        let mut names = BTreeSet::new();
        for action in actions {
            assert_eq!(HostAction::parse(action.label()).unwrap(), action);
            if action == HostAction::Upload {
                for role in &roles {
                    let name = host_receipt_name(action, role)
                        .unwrap_or_else(|error| panic!("canonical upload role {role}: {error}"));
                    assert_eq!(name, format!("upload-{role}.json"));
                    validate_receipt_name(&name).expect("shared receipt namespace");
                    assert!(names.insert(name), "canonical receipt names must be unique");
                }
            } else {
                let name = host_receipt_name(action, "")
                    .unwrap_or_else(|error| panic!("canonical action {action:?}: {error}"));
                assert_eq!(name, format!("{}.json", action.label()));
                validate_receipt_name(&name).expect("shared receipt namespace");
                assert!(names.insert(name), "canonical receipt names must be unique");
            }
        }
        // The upload fixture uses the exact inventory role constants, so a new
        // canonical artifact role automatically participates in this gate.
        assert!(names.contains("upload-iroha3d.json"));
        assert!(names.contains("upload-iroha_cli.json"));
        assert!(names.contains("inrou_stage_upload.json"));
    }

    #[test]
    fn receipt_names_reject_path_control_and_unicode_escape() {
        for name in [
            "",
            ".",
            "..",
            "receipt",
            "../receipt.json",
            "/receipt.json",
            "dir/receipt.json",
            "dir\\receipt.json",
            "receipt.json/..",
            "receipt.json\0",
            "receipt.json\n",
            "receipt.json\r",
            "receipt\t.json",
            "receipt name.json",
            "Receipt.json",
            "réceipt.json",
            "receipt．json",
        ] {
            assert!(
                validate_receipt_name(name).is_err(),
                "unsafe receipt {name:?}"
            );
        }
        let longest = format!("{}.json", "a".repeat(123));
        validate_receipt_name(&longest).expect("exact 128-byte bound");
        assert!(validate_receipt_name(&format!("a{longest}")).is_err());
        for role in [
            "",
            "../iroha_cli",
            "iroha/cli",
            "iroha\\cli",
            "iroha.cli",
            "iroha-cli",
            "iroha_cli\0",
            "iroha_cli\n",
            "iróha_cli",
        ] {
            assert!(
                host_receipt_name(HostAction::Upload, role).is_err(),
                "unsafe role {role:?}"
            );
        }
        assert!(host_receipt_name(HostAction::Upload, &"a".repeat(65)).is_err());
    }

    #[test]
    fn host_progress_requires_explicit_nullable_prepared_action_slot() {
        let admitted = progress_admission();
        let progress = initial_host_progress(&admitted);
        let canonical = json::to_value(&progress).expect("host-progress JSON value");
        assert!(
            canonical
                .as_object()
                .and_then(|object| object.get("prepared_action"))
                .is_some_and(norito::json::Value::is_null),
            "empty host progress must serialize an explicit prepared_action null slot"
        );
        json::from_value::<HostProgressV1>(canonical.clone())
            .expect("explicit nullable host-progress slot");

        let mut missing = canonical;
        missing
            .as_object_mut()
            .expect("host-progress object")
            .remove("prepared_action");
        assert!(
            json::from_value::<HostProgressV1>(missing).is_err(),
            "the exact V1 host progress must reject an omitted prepared_action slot"
        );
    }

    #[test]
    fn beacon_activation_barrier_preserves_pre_ready_bootstrap_and_blocks_later_mutations() {
        let mut admitted = progress_admission();
        let plan = host_forward_plan(&admitted);
        let activation = plan
            .iter()
            .position(|key| key.action == HostAction::BeaconActivate.label())
            .unwrap();
        let after_activation = activation + 4;
        assert_eq!(
            plan[activation..after_activation]
                .iter()
                .map(|key| (key.host_slug.as_str(), key.action.as_str()))
                .collect::<Vec<_>>(),
            [
                ("taira-validator-1", HostAction::BeaconActivate.label()),
                ("taira-validator-2", HostAction::BeaconActivate.label()),
                ("taira-validator-3", HostAction::BeaconActivate.label()),
                ("taira-validator-4", HostAction::BeaconActivate.label()),
            ]
        );
        assert!(
            plan[..activation]
                .iter()
                .rev()
                .take(4)
                .all(|key| key.action == HostAction::Start.label())
        );
        let mut progress = initial_host_progress(&admitted);
        progress.next_forward_ordinal = u16::try_from(activation).unwrap();
        admitted.request.mutation_phase = "pre_edge".into();
        for kind in ["onboarding", "faucet", "write_canary"] {
            admitted.request.mutation_kind = kind.into();
            validate_prepared_mutation_progress(&admitted, &progress).unwrap();
        }
        admitted.request.mutation_kind = "inrou_bundle_pin".into();
        assert!(validate_prepared_mutation_progress(&admitted, &progress).is_err());
        progress.next_forward_ordinal = u16::try_from(after_activation).unwrap();
        assert!(validate_prepared_mutation_progress(&admitted, &progress).is_err());
        admitted.request.mutation_kind = "write_canary".into();
        assert!(validate_prepared_mutation_progress(&admitted, &progress).is_err());
        select_target(&mut admitted, "taira-validator-1");
        progress.next_forward_ordinal = u16::try_from(activation).unwrap();
        assert_eq!(
            admit_host_action_progress(&admitted, HostAction::BeaconActivate, &progress).unwrap(),
            HostProgressDecision::Advance
        );
        assert!(admit_host_action_progress(&admitted, HostAction::Restart, &progress).is_err());
    }

    #[test]
    fn shared_host_progress_enforces_cohort_barriers_and_exact_rollback_target() {
        let mut admitted = progress_admission();
        let plan = host_forward_plan(&admitted);
        let stop_one = HostActionKeyV1 {
            host_slug: "taira-validator-1".to_owned(),
            action: HostAction::Stop.label().to_owned(),
            artifact_role: String::new(),
        };
        let stop_ordinal = plan
            .iter()
            .position(|key| key == &stop_one)
            .expect("stop ordinal");
        let mut progress = initial_host_progress(&admitted);
        progress.next_forward_ordinal = u16::try_from(stop_ordinal + 1).expect("bounded plan");
        progress.touched_hosts.push(stop_one.host_slug.clone());

        select_target(&mut admitted, "taira-validator-1");
        assert_eq!(
            admit_host_action_progress(&admitted, HostAction::Install, &progress)
                .expect_err("install must wait for every validator stop")
                .to_string(),
            "host action violates the exact monotonic physical-host phase order"
        );
        assert_eq!(
            admit_host_action_progress(&admitted, HostAction::Rollback, &progress)
                .expect("only touched validator is exact rollback target"),
            HostProgressDecision::Advance
        );
        select_target(&mut admitted, "taira-validator-2");
        assert_eq!(
            admit_host_action_progress(&admitted, HostAction::Rollback, &progress)
                .expect("untouched conservative target must be a proven no-op"),
            HostProgressDecision::AbsentNoOp
        );
        select_target(&mut admitted, "taira-validator-1");
        assert_eq!(
            admit_host_action_progress(&admitted, HostAction::Rollback, &progress)
                .expect("the exact touched target remains next after absent no-op"),
            HostProgressDecision::Advance
        );
    }

    #[test]
    fn completed_host_action_replay_preserves_a_later_prepared_action_and_exact_receipt() {
        let mut admitted = progress_admission();
        let plan = host_forward_plan(&admitted);
        let later = plan
            .iter()
            .position(|key| {
                key.host_slug == "taira-validator-2" && key.action == HostAction::Install.label()
            })
            .expect("second validator install");
        let mut progress = initial_host_progress(&admitted);
        progress.next_forward_ordinal = u16::try_from(later).unwrap();
        progress.prepared_action = Some(plan[later].clone());
        progress.touched_hosts = admitted
            .inventory
            .validators
            .iter()
            .map(|validator| validator.slug.clone())
            .collect();
        let before = json::to_json(&progress).unwrap();

        select_target(&mut admitted, "taira-validator-1");
        assert_eq!(
            admit_host_action_progress(&admitted, HostAction::Install, &progress).unwrap(),
            HostProgressDecision::Replay
        );
        assert_eq!(json::to_json(&progress).unwrap(), before);

        let directory = super::super::private_custody_test_dir("completed-host-action-replay-");
        let name = host_receipt_name(HostAction::Install, "").unwrap();
        assert!(
            read_existing_host_receipt(directory.path(), &name, &admitted, HostAction::Install)
                .unwrap()
                .is_none()
        );
        let path = directory.path().join(&name);
        let mut receipt = host_receipt(&admitted, HostAction::Install, false, 0, 0, "installed");
        let bytes = json::to_json(&receipt).unwrap();
        fs::write(&path, &bytes).unwrap();
        fs::set_permissions(&path, fs::Permissions::from_mode(0o600)).unwrap();
        let inode = fs::symlink_metadata(&path).unwrap().ino();
        read_existing_host_receipt(directory.path(), &name, &admitted, HostAction::Install)
            .unwrap()
            .expect("exact completed action receipt");
        assert_eq!(fs::read_to_string(&path).unwrap(), bytes);
        assert_eq!(fs::symlink_metadata(&path).unwrap().ino(), inode);
        receipt.request_sha256 = "e".repeat(64);
        fs::write(&path, json::to_json(&receipt).unwrap()).unwrap();
        assert!(
            read_existing_host_receipt(directory.path(), &name, &admitted, HostAction::Install)
                .is_err()
        );

        select_target(&mut admitted, "taira-validator-2");
        assert_eq!(
            admit_host_action_progress(&admitted, HostAction::Install, &progress).unwrap(),
            HostProgressDecision::Advance
        );
        select_target(&mut admitted, "taira-validator-3");
        assert!(admit_host_action_progress(&admitted, HostAction::Install, &progress).is_err());
        select_target(&mut admitted, "taira-validator-1");
        assert!(admit_host_action_progress(&admitted, HostAction::Reset, &progress).is_err());
        progress.rolling_back = true;
        assert!(admit_host_action_progress(&admitted, HostAction::Install, &progress).is_err());
        progress.rolling_back = false;
        progress.prepared_action = None;
        select_target(&mut admitted, "taira-validator-3");
        assert!(admit_host_action_progress(&admitted, HostAction::Install, &progress).is_err());
        assert_eq!(progress.next_forward_ordinal, u16::try_from(later).unwrap());
    }

    #[test]
    fn rollback_historical_marker_requires_the_signed_prior_inode_and_foreign_authorization() {
        let admitted = progress_admission();
        let directory = tempfile::tempdir().unwrap();
        let metadata = fs::symlink_metadata(directory.path()).unwrap();
        let mut validator = admitted.inventory.validators[0].clone();
        let super::super::ValidatorInitialStateV1::AdmittedRelease(prior) =
            &mut validator.initial_state
        else {
            panic!("occupied predecessor fixture");
        };
        prior.service_state =
            PriorValidatorServiceStateV1::Stopped(super::super::StoppedValidatorStateV1 {
                device: metadata.dev(),
                inode: metadata.ino(),
            });
        let marker = GeneratedMarkerV1 {
            schema: GENERATED_MARKER_SCHEMA_V1.into(),
            kind: "fresh_state".into(),
            host_slug: validator.slug.clone(),
            inventory_sha256: "e".repeat(64),
            authorization_nonce: "f".repeat(32),
            revision: "c".repeat(40),
            created_at_unix_ms: 1,
        };
        let check = |marker: &GeneratedMarkerV1, validator: &ValidatorV1, device, inode| {
            validate_historical_prior_state_marker(marker, &admitted, validator, device, inode)
        };
        check(&marker, &validator, metadata.dev(), metadata.ino()).unwrap();
        assert!(check(&marker, &validator, metadata.dev() ^ 1, metadata.ino()).is_err());
        assert!(check(&marker, &validator, metadata.dev(), metadata.ino() + 1).is_err());
        for field in [
            "current_nonce",
            "current_inventory",
            "schema",
            "kind",
            "host",
            "inventory",
            "nonce",
            "revision",
            "time",
        ] {
            let mut wrong = marker.clone();
            match field {
                "current_nonce" => {
                    wrong.authorization_nonce = admitted.inventory.authorization_nonce.clone()
                }
                "current_inventory" => wrong.inventory_sha256 = admitted.inventory_sha256.clone(),
                "schema" => wrong.schema = "unknown".into(),
                "kind" => wrong.kind = "release".into(),
                "host" => wrong.host_slug = "taira-validator-2".into(),
                "inventory" => wrong.inventory_sha256 = "not-a-hash".into(),
                "nonce" => wrong.authorization_nonce = "not-a-nonce".into(),
                "revision" => wrong.revision = "not-a-revision".into(),
                "time" => wrong.created_at_unix_ms = 0,
                _ => unreachable!(),
            }
            assert!(
                check(&wrong, &validator, metadata.dev(), metadata.ino()).is_err(),
                "accepted {field} drift"
            );
        }
        let mut running = validator.clone();
        let super::super::ValidatorInitialStateV1::AdmittedRelease(prior) =
            &mut running.initial_state
        else {
            unreachable!();
        };
        prior.service_state = PriorValidatorServiceStateV1::Running;
        assert!(check(&marker, &running, metadata.dev(), metadata.ino()).is_err());
        let mut vacant = validator.clone();
        vacant.initial_state = super::super::ValidatorInitialStateV1::Vacant;
        assert!(check(&marker, &vacant, metadata.dev(), metadata.ino()).is_err());
    }

    #[test]
    fn edge_cutover_is_touched_first_and_success_seal_forbids_rollback() {
        let mut admitted = progress_admission();
        let edge = admitted.inventory.edge.slug.clone();
        let mut guest_progress = initial_host_progress(&admitted);
        guest_progress.touched_hosts.push(edge.clone());
        assert!(validate_host_progress(&admitted, &guest_progress).is_err());
        select_target(&mut admitted, &edge);
        let plan = host_forward_plan(&admitted);
        let cutover = HostActionKeyV1 {
            host_slug: edge.clone(),
            action: HostAction::EdgeCutover.label().to_owned(),
            artifact_role: String::new(),
        };
        assert!(host_action_touches_live_state(&cutover));
        let mut progress = initial_host_progress(&admitted);
        progress.touched_hosts = vec![edge.clone()];
        progress.next_forward_ordinal = u16::try_from(
            plan.iter()
                .position(|key| key == &cutover)
                .expect("cutover ordinal"),
        )
        .expect("bounded plan");
        progress.prepared_action = Some(cutover);
        let mut foreign_host = progress.clone();
        foreign_host
            .touched_hosts
            .insert(0, "taira-validator-1".to_owned());
        assert!(validate_host_progress(&admitted, &foreign_host).is_err());
        assert_eq!(
            admit_host_action_progress(&admitted, HostAction::Rollback, &progress)
                .expect("edge is exact first rollback target"),
            HostProgressDecision::Advance
        );

        let first_seal = plan
            .iter()
            .position(|key| key.action == HostAction::Seal.label())
            .expect("seal ordinal");
        progress.next_forward_ordinal = u16::try_from(first_seal + 1).expect("bounded plan");
        progress.prepared_action = None;
        progress.touched_hosts.clear();
        assert!(
            admit_host_action_progress(&admitted, HostAction::Rollback, &progress).is_err(),
            "sealing deployment must reject every rollback"
        );
    }

