    pub(in crate::taira_public_reset) fn core_proof_required_store_fixture(
        origin: &str,
    ) -> (CoreWriteIdentity, Vec<u8>, Vec<u8>, String) {
        let (admitted, prepared, envelope, _, _) = authenticated_proof_required_fixture(origin);
        let identity = CoreWriteIdentity::from_inventory(
            &admitted.inventory,
            &admitted.authorization,
            &admitted.authorization_sha256,
            &prepared.phase,
        )
        .expect("fixture core identity");
        let evidence = proof_required_evidence(&admitted, &prepared);
        (identity, envelope, evidence, prepared.idempotency_key)
    }

    fn authenticated_proof_required_fixture(
        public_root: &str,
    ) -> (HostAdmission, PreparedMutationV1, Vec<u8>, String, String) {
        let fixture: norito::json::Value = json::from_str(include_str!(
            "../../../fixtures/prepared_transactions/prepared_transaction_signature_v1.json"
        ))
        .expect("prepared signature fixture");
        let vectors = fixture
            .as_object()
            .and_then(|root| root.get("vectors"))
            .and_then(norito::json::Value::as_array)
            .expect("fixture vectors");
        let vector = |name: &str| {
            vectors
                .iter()
                .find(|vector| {
                    vector
                        .as_object()
                        .and_then(|vector| vector.get("name"))
                        .and_then(norito::json::Value::as_str)
                        == Some(name)
                })
                .and_then(norito::json::Value::as_object)
                .expect("named fixture vector")
        };
        let prepared_vector = vector("onboarding_prepared");
        let proof_vector = vector("onboarding_proof_required");
        let receipt = prepared_vector
            .get("response")
            .and_then(norito::json::Value::as_object)
            .and_then(|response| response.get("receipt"))
            .cloned()
            .expect("fixture onboarding receipt");
        let result = proof_vector
            .get("response")
            .cloned()
            .expect("fixture proof-required result");
        let typed_receipt: AccountOnboardingPlanReceiptV1 =
            json::from_value(receipt.clone()).expect("typed fixture receipt");
        let typed_result: AccountOnboardingProofRequiredPrepareResponseV1 =
            json::from_value(result.clone()).expect("typed fixture proof result");
        let network_id_value = proof_vector.get("network_id").expect("fixture network id");
        let network_id: NetworkId =
            json::from_value(network_id_value.clone()).expect("typed fixture network id");
        let network_id_literal = network_id_value
            .as_str()
            .expect("string fixture network id");

        let mut admitted = progress_admission();
        admitted.inventory.chain_id = "fixture-chain".to_owned();
        admitted.inventory.next_genesis_hash = hex::encode(network_id.as_bytes());
        admitted
            .inventory
            .inrou_canary
            .as_mut()
            .expect("full Inrou fixture")
            .public_root = public_root.to_owned();
        admitted.inventory.validator_clients[0].probe_origin =
            format!("{}/", public_root.trim_end_matches('/'));
        admitted.inventory.canary_onboarding_request = typed_receipt.body.request.clone();
        let native_binding = crate::taira::PreparedMutationBindingV1 {
            schema: crate::taira::PreparedMutationBindingV1::SCHEMA.to_owned(),
            authorization_sha256: "11".repeat(32),
            authorization_nonce: "n".repeat(32),
            kind: "onboarding".to_owned(),
            phase: "pre_edge".to_owned(),
            idempotency_key: typed_result.binding.request_id.clone(),
            execution_expires_at_unix_ms: typed_result.binding.execution_expires_at_unix_ms,
        };
        admitted.inventory.authorization_nonce = native_binding.authorization_nonce.clone();
        admitted.authorization_sha256 = native_binding.authorization_sha256.clone();
        admitted.authorization.claims.authorization_nonce =
            native_binding.authorization_nonce.clone();
        admitted.authorization.claims.execution_expires_at_unix_ms =
            typed_result.binding.execution_expires_at_unix_ms;
        admitted.request.authorization_semantic_sha256 = admitted.authorization_sha256.clone();
        admitted.request.mutation_kind = typed_result.binding.kind.clone();
        admitted.request.mutation_phase = native_binding.phase.clone();
        admitted.request.mutation_idempotency_key = native_binding.idempotency_key.clone();
        admitted.action_deadline = Instant::now() + Duration::from_secs(10);
        // This captured signed proof fixture deliberately uses a foreign chain_id. Its
        // inventory is only hashed here, never passed to the Taira admission decoder.
        let inventory_bytes = {
            let _guard = ChainDiscriminantGuard::enter(super::super::CHAIN_DISCRIMINANT);
            json::to_vec(&admitted.inventory).expect("foreign-chain proof fixture inventory")
        };
        admitted.inventory_sha256 = sha256_hex(&inventory_bytes);

        let envelope = norito::json!({
            "schema": "iroha.taira.prepared-mutation-envelope.v1",
            "binding": (json::to_value(&native_binding).expect("native fixture custody")),
            "public_root": public_root,
            "chain_id": (admitted.inventory.chain_id.clone()),
            "network_id": network_id_literal,
            "authority": (typed_receipt.body.request.account_id.clone()),
            "operation": {
                "kind": "onboarding_proof_required",
                "envelope": {
                    "schema": "iroha.taira.prepared-onboarding-proof-required.v1",
                    "receipt": receipt,
                    "result": result,
                }
            }
        });
        let mut bytes = json::to_json(&envelope)
            .expect("canonical proof-required envelope")
            .into_bytes();
        bytes.push(b'\n');
        let (digest, transaction_hash, operation) = validate_prepared_mutation_envelope(
            &admitted,
            &bytes,
            PreparedMutationLifetimeCheck::LiveForward,
        )
        .expect("authenticated fixture proof-required envelope");
        let prepared = PreparedMutationV1 {
            schema: PREPARED_MUTATION_SCHEMA_V1.to_owned(),
            inventory_sha256: admitted.inventory_sha256.clone(),
            authorization_sha256: admitted.authorization_sha256.clone(),
            authorization_nonce: admitted.inventory.authorization_nonce.clone(),
            kind: admitted.request.mutation_kind.clone(),
            phase: admitted.request.mutation_phase.clone(),
            idempotency_key: admitted.request.mutation_idempotency_key.clone(),
            operation,
            prepared_base64: BASE64.encode(&bytes),
            prepared_sha256: digest,
            transaction_hash,
        };
        (
            admitted,
            prepared,
            bytes,
            typed_result.account_id,
            typed_result.alias,
        )
    }

    #[test]
    fn typed_write_envelope_producer_reaches_authenticated_host_consumer() {
        // The captured signed fixture uses SORA-discriminant account literals.
        let _chain = ChainDiscriminantGuard::enter(0x02f1);
        let (admitted, prepared, fixture_bytes, _, _) =
            authenticated_proof_required_fixture("http://127.0.0.1:8080");
        let value = json::from_slice(&fixture_bytes).expect("authenticated fixture JSON");
        let produced = crate::taira::typed_write_envelope_bytes_for_test(value)
            .expect("real typed CLI envelope producer");
        let (digest, transaction_hash, operation) = validate_prepared_mutation_envelope(
            &admitted,
            &produced,
            PreparedMutationLifetimeCheck::LiveForward,
        )
        .expect("actual host consumer accepts typed producer bytes and verifies signatures");
        assert_eq!(produced, fixture_bytes);
        assert_eq!(digest, prepared.prepared_sha256);
        assert_eq!(transaction_hash, prepared.transaction_hash);
        assert_eq!(operation, prepared.operation);
    }

    #[test]
    fn interrupted_onboarding_proof_recovers_from_its_authenticated_prepared_envelope() {
        let _chain = ChainDiscriminantGuard::enter(0x02f1);
        let (_, prepared, bytes, _, _) =
            authenticated_proof_required_fixture("http://127.0.0.1:8080");
        let mut retained = RetainedPreparedMutation {
            state: "prepared".to_owned(),
            bytes,
            sha256: prepared.prepared_sha256,
            transaction_hash: prepared.transaction_hash,
        };
        assert!(
            retained
                .write_recovery_requires_observation("onboarding")
                .unwrap(),
            "an interrupted atomic state proof has no Submitted transaction marker"
        );
        assert!(
            retained
                .write_recovery_requires_observation("faucet")
                .is_err()
        );
        assert!(
            retained
                .write_recovery_requires_observation("write_canary")
                .is_err()
        );
        retained.bytes.push(b' ');
        assert!(
            retained
                .write_recovery_requires_observation("onboarding")
                .is_err()
        );
        retained.bytes.pop();

        for state in ["prepared", "submitted", "applied"] {
            retained.state = state.to_owned();
            let outcome = retain_applied_mutation_outcome(
                &retained,
                PreparedMutationOutcome::Rejected("Rejected".to_owned()),
            );
            assert_eq!(
                matches!(outcome, PreparedMutationOutcome::Pending),
                state == "applied",
                "a contradictory observation cannot revoke retained Applied custody"
            );
        }
        retained.state = "prepared".to_owned();
        retained.transaction_hash = "11".repeat(32);
        assert!(
            !retained
                .write_recovery_requires_observation("onboarding")
                .unwrap(),
            "a real transaction still requires its exact Submitted marker"
        );
        retained.state = "submitted".to_owned();
        assert!(
            retained
                .write_recovery_requires_observation("onboarding")
                .unwrap()
        );
        retained.state = "absent".to_owned();
        assert!(
            !retained
                .write_recovery_requires_observation("onboarding")
                .unwrap()
        );
    }

    fn proof_required_evidence(admitted: &HostAdmission, prepared: &PreparedMutationV1) -> Vec<u8> {
        let envelope = BASE64
            .decode(&prepared.prepared_base64)
            .expect("prepared envelope base64");
        let result = prepared_onboarding_proof_required_result(&envelope)
            .expect("typed proof-required result");
        let report = norito::json!({
            "command": "taira_write_canary",
            "status": "ok",
            "public_root": (mutation_probe_root(&admitted.inventory, &prepared.phase).unwrap()),
            "checks": [],
            "warnings": [],
            "failures": [],
            "authorization_sha256": (admitted.authorization_sha256.clone()),
            "authorization_nonce": (admitted.inventory.authorization_nonce.clone()),
            "mutation_kind": "onboarding",
            "mutation_phase": (prepared.phase.clone()),
            "idempotency_key": (prepared.idempotency_key.clone()),
            "operation": "onboarding",
            "recovery_outcome": "Applied",
            "prepared_envelope_sha256": (prepared.prepared_sha256.clone()),
            "prepared_envelope_size": (u64::try_from(envelope.len()).expect("bounded envelope")),
            "transaction_hash_hex": null,
            "applied_block_height": null,
            "evidence": (result.semantic_hash_hex),
            "execution_expires_at_unix_ms": (admitted.authorization.claims.execution_expires_at_unix_ms),
        });
        let mut bytes = json::to_json(&report)
            .expect("canonical proof-required evidence")
            .into_bytes();
        bytes.push(b'\n');
        bytes
    }

