    fn exercise_atomic_proof_response(
        body: norito::json::Value,
        execution_expired: bool,
    ) -> (Result<String>, String) {
        let (public_root, server) = spawn_atomic_proof_server(200, body);
        let (mut admitted, prepared, _, _, _) = authenticated_proof_required_fixture(&public_root);
        admitted.execution_expired = execution_expired;
        let evidence = proof_required_evidence(&admitted, &prepared);
        let result =
            validate_prepared_mutation_proof_required_evidence(&admitted, &prepared, &evidence);
        (result, server.join().expect("atomic proof server joins"))
    }

    fn assert_exact_atomic_proof_post(request: &str, account_id: &str, alias: &str) {
        assert!(request.starts_with("POST /v1/accounts/onboarding/current-state HTTP/1.1\r\n"));
        assert!(!request.contains("GET /status"));
        assert!(!request.contains("GET /v1/accounts/"));
        assert!(!request.contains("POST /v1/aliases/resolve"));
        let (_, body) = request
            .split_once("\r\n\r\n")
            .expect("atomic proof request has a body separator");
        let decoded: AccountOnboardingCurrentStateRequestV1 =
            json::from_str(body).expect("atomic proof request is exact typed V1 JSON");
        assert_eq!(
            decoded.version,
            AccountOnboardingCurrentStateRequestV1::VERSION
        );
        assert_eq!(decoded.account_id, account_id);
        assert_eq!(decoded.alias, alias);
    }

    #[test]
    fn proof_required_reopens_with_one_atomic_post_even_after_expiry() {
        let (response, account_id, alias) = exact_atomic_state_fixture();
        let (result, request) = exercise_atomic_proof_response(
            json::to_value(&response).expect("encode exact atomic response"),
            true,
        );
        result.expect("one atomic snapshot proves the exact no-op");
        assert_exact_atomic_proof_post(&request, &account_id, &alias);
    }

    #[test]
    fn proof_required_atomic_state_rejects_network_version_and_identity_substitution() {
        let (response, account_id, alias) = exact_atomic_state_fixture();
        let foreign_key =
            iroha_crypto::KeyPair::try_from_seed(vec![0x76; 32], iroha_crypto::Algorithm::Ed25519)
                .expect("foreign key");
        let foreign_account = AccountId::new(foreign_key.public_key().clone()).to_string();
        let mut candidates = Vec::new();

        let mut foreign_network = response.clone();
        foreign_network.network_id = NetworkId::from_genesis_hash(
            HashOf::<BlockHeader>::from_untyped_unchecked(Hash::new(b"foreign-atomic-network")),
        );
        candidates.push(foreign_network);
        let mut wrong_version = response.clone();
        wrong_version.version = AccountOnboardingCurrentStateResponseV1::VERSION + 1;
        candidates.push(wrong_version);
        let mut wrong_account = response.clone();
        wrong_account.account_id = foreign_account;
        candidates.push(wrong_account);
        let mut wrong_alias = response;
        wrong_alias.alias = "other@banka.paynet".to_owned();
        candidates.push(wrong_alias);

        for candidate in candidates {
            let (result, request) = exercise_atomic_proof_response(
                json::to_value(&candidate).expect("encode substituted atomic response"),
                false,
            );
            let _error =
                result.expect_err("atomic network, version, and identity substitution must fail");
            assert_exact_atomic_proof_post(&request, &account_id, &alias);
        }
    }

    #[test]
    fn proof_required_atomic_state_rejects_account_and_alias_absence() {
        let (response, account_id, alias) = exact_atomic_state_fixture();
        let mut account_missing = response.clone();
        account_missing.account_exists = false;
        account_missing.alias_target_account_id = None;
        let mut alias_missing = response;
        alias_missing.alias_target_account_id = None;

        for (candidate, expected) in [
            (account_missing, "exact account absent"),
            (alias_missing, "exact alias absent"),
        ] {
            let (result, request) = exercise_atomic_proof_response(
                json::to_value(&candidate).expect("encode absent atomic response"),
                false,
            );
            let error = result.expect_err("absent account or alias must remain nonterminal");
            assert!(
                error.to_string().contains(expected),
                "unexpected error: {error:#}"
            );
            assert_exact_atomic_proof_post(&request, &account_id, &alias);
        }
    }

    #[test]
    fn proof_required_atomic_state_rejects_an_alias_target_conflict() {
        let (mut response, account_id, alias) = exact_atomic_state_fixture();
        let conflict_key =
            iroha_crypto::KeyPair::try_from_seed(vec![0x77; 32], iroha_crypto::Algorithm::Ed25519)
                .expect("conflict key");
        response.alias_target_account_id =
            Some(AccountId::new(conflict_key.public_key().clone()).to_string());
        let (result, request) = exercise_atomic_proof_response(
            json::to_value(&response).expect("encode conflicting atomic response"),
            false,
        );
        let error = result.expect_err("conflicting alias target must remain nonterminal");
        assert!(error.to_string().contains("alias target conflict"));
        assert_exact_atomic_proof_post(&request, &account_id, &alias);
    }

    #[test]
    fn proof_required_atomic_state_rejects_zero_or_untyped_anchor() {
        let (response, account_id, alias) = exact_atomic_state_fixture();
        let mut zero_height = response.clone();
        zero_height.observed_block_height = 0;
        let (result, request) = exercise_atomic_proof_response(
            json::to_value(&zero_height).expect("encode zero-height atomic response"),
            false,
        );
        let error = result.expect_err("zero-height atomic response must fail");
        assert!(error.to_string().contains("zero committed height"));
        assert_exact_atomic_proof_post(&request, &account_id, &alias);

        let mut invalid_hash =
            json::to_value(&response).expect("encode invalid-hash atomic response");
        invalid_hash
            .as_object_mut()
            .expect("atomic response object")
            .insert(
                "observed_block_hash".to_owned(),
                norito::json::Value::from("not-a-typed-block-hash"),
            );
        let (result, request) = exercise_atomic_proof_response(invalid_hash, false);
        let _error = result.expect_err("untyped atomic block hash must fail closed");
        assert_exact_atomic_proof_post(&request, &account_id, &alias);
    }

    #[test]
    fn host_frontier_preserves_four_beacon_activations_before_cutover() {
        let admitted = progress_admission();
        let plan = host_forward_plan(&admitted);
        let positions = |action: HostAction| {
            plan.iter()
                .enumerate()
                .filter_map(|(index, key)| (key.action == action.label()).then_some(index))
                .collect::<Vec<_>>()
        };
        let activations = positions(HostAction::BeaconActivate);
        assert_eq!(activations.len(), 4);
        assert!(
            positions(HostAction::Start)
                .iter()
                .all(|i| *i < activations[0])
        );
        assert!(positions(HostAction::Restart).is_empty());
        assert!(positions(HostAction::EdgeStage).is_empty());
        assert!(
            positions(HostAction::Seal)
                .iter()
                .all(|i| *i > activations[3])
        );
        for action in [
            "epoch_supervisor_pause",
            "epoch_supervisor_start",
            "epoch_supervisor_rollback_pause",
            "epoch_supervisor_rollback_restore",
        ] {
            assert!(HostAction::parse(action).is_err());
            assert!(!plan.iter().any(|key| key.action == action));
        }
        let canary = build_recovery_intent(&admitted.inventory, ExecutionStep::Canary).unwrap();
        assert_eq!(canary.mutations[7].kind, "beacon_provider_4");
        assert_eq!(canary.mutations.len(), 8);
        assert!(
            canary
                .mutations
                .iter()
                .all(|mutation| mutation.phase == "pre_edge")
        );
    }

    #[test]
    fn recovery_intent_exposes_every_ordered_child_mutation() {
        let inventory = super::super::sample_inventory_fixture();
        let canary = build_recovery_intent(&inventory, ExecutionStep::Canary)
            .expect("canary recovery intent");
        assert_eq!(canary.mutations.len(), 8);
        assert_eq!(
            canary
                .mutations
                .iter()
                .map(|mutation| mutation.kind.as_str())
                .collect::<Vec<_>>(),
            [
                "onboarding",
                "faucet",
                "write_canary",
                "beacon_install",
                "beacon_provider_1",
                "beacon_provider_2",
                "beacon_provider_3",
                "beacon_provider_4",
            ]
        );
        let restart = build_recovery_intent(&inventory, ExecutionStep::RestartProof)
            .expect("restart recovery intent");
        assert_eq!(restart.mutations.len(), 16);
        for wave in 0..4 {
            assert_eq!(restart.mutations[wave * 4].kind, "host_restart");
            assert_eq!(
                restart.mutations[wave * 4 + 1..wave * 4 + 4]
                    .iter()
                    .map(|mutation| mutation.kind.as_str())
                    .collect::<Vec<_>>(),
                ["onboarding", "faucet", "write_canary"]
            );
        }
        assert!(build_recovery_intent(&inventory, ExecutionStep::EdgeVerify).is_none());
    }

    #[test]
    fn core_testnet_scope_preserves_baseline_recovery_and_host_plan() {
        let mut admitted = progress_admission();
        let full_plan = host_forward_plan(&admitted);
        let full_canary = build_recovery_intent(&admitted.inventory, ExecutionStep::Canary)
            .expect("full qualification intent");
        let full_restart = build_recovery_intent(&admitted.inventory, ExecutionStep::RestartProof)
            .expect("full restart intent");
        admitted.inventory.qualification_scope = super::super::QualificationScopeV1::CoreTestnet;
        admitted.inventory.inrou_canary = None;
        admitted.inventory.inrou_stage_tree_sha256 = None;
        admitted.authorization.claims.inrou_stage_tree_sha256 = None;
        let core_plan = host_forward_plan(&admitted);
        assert!(!core_plan.iter().any(|key| {
            [
                HostAction::InrouStageUpload.label(),
                HostAction::Preseed.label(),
            ]
            .contains(&key.action.as_str())
        }));
        assert_eq!(
            core_plan
                .iter()
                .filter(|key| ![
                    HostAction::Restart.label(),
                    HostAction::InrouStageUpload.label(),
                    HostAction::Preseed.label()
                ]
                .contains(&key.action.as_str()))
                .collect::<Vec<_>>(),
            full_plan
                .iter()
                .filter(|key| ![
                    HostAction::Restart.label(),
                    HostAction::InrouStageUpload.label(),
                    HostAction::Preseed.label()
                ]
                .contains(&key.action.as_str()))
                .collect::<Vec<_>>(),
            "all four validators retain artifact custody, staging, start and seal actions"
        );
        assert!(
            core_plan
                .iter()
                .chain(&full_plan)
                .all(|key| key.action != HostAction::Restart.label()),
            "neither deployment scope schedules diagnostic restarts"
        );
        assert!(!admitted.inventory.qualification_scope.includes_inrou());
        let canary = build_recovery_intent(&admitted.inventory, ExecutionStep::Canary)
            .expect("core qualification intent");
        assert_eq!(
            canary
                .mutations
                .iter()
                .map(|mutation| mutation.kind.as_str())
                .collect::<Vec<_>>(),
            [
                "onboarding",
                "faucet",
                "write_canary",
                "beacon_install",
                "beacon_provider_1",
                "beacon_provider_2",
                "beacon_provider_3",
                "beacon_provider_4"
            ]
        );
        assert!(recovery_intent_identity_matches(&canary, &full_canary));
        assert!(recovery_intent_identity_matches(&full_canary, &canary));
        let restart = build_recovery_intent(&admitted.inventory, ExecutionStep::RestartProof)
            .expect("core restart intent");
        assert_eq!(restart.mutations.len(), 4);
        assert_eq!(
            restart
                .mutations
                .iter()
                .map(|mutation| mutation.kind.as_str())
                .collect::<Vec<_>>(),
            ["host_restart", "onboarding", "faucet", "write_canary"]
        );
        assert!(
            restart
                .mutations
                .iter()
                .all(|mutation| mutation.phase == "restart-wave-1")
        );
        assert!(!recovery_intent_identity_matches(&restart, &full_restart));
        assert!(!recovery_intent_identity_matches(&full_restart, &restart));
        for cursor in 0..=restart.mutations.len() {
            let mut resumed = restart.clone();
            resumed.next_mutation = u16::try_from(cursor).expect("bounded cursor");
            for mutation in resumed.mutations.iter_mut().take(cursor) {
                mutation.state = RecoveryMutationStateV1::Applied;
            }
            super::super::validate_recovery_intent(&resumed, ExecutionStep::RestartProof)
                .expect("every exact core cursor reopens");
            assert!(recovery_intent_identity_matches(&resumed, &restart));
            if cursor < resumed.mutations.len() {
                resumed.mutations[cursor].state = RecoveryMutationStateV1::Submitted;
                super::super::validate_recovery_intent(&resumed, ExecutionStep::RestartProof)
                    .expect("a submitted core child retains read-only recovery");
                assert!(!super::super::recovery_ready_to_continue(
                    &resumed,
                    ExecutionStep::RestartProof,
                ));
            }
            if cursor > 0 {
                resumed.mutations[cursor - 1].state = RecoveryMutationStateV1::Prepared;
                assert!(
                    super::super::validate_recovery_intent(&resumed, ExecutionStep::RestartProof)
                        .is_err(),
                    "the shorter plan cannot skip an unapplied predecessor"
                );
            }
        }
        let mut overrun = restart.clone();
        overrun.next_mutation = 5;
        assert!(
            super::super::validate_recovery_intent(&overrun, ExecutionStep::RestartProof).is_err()
        );
        assert!(build_recovery_intent(&admitted.inventory, ExecutionStep::EdgeVerify).is_none());
        let envelopes = canary
            .mutations
            .iter()
            .chain(&restart.mutations)
            .filter(|mutation| mutation.kind != "host_restart")
            .count();
        assert_eq!(
            envelopes, 11,
            "bootstrap and explicitly constructed restart intent retain immutable custody"
        );
        admitted.request.mutation_kind = "write_canary".to_owned();
        for phase in ["pre_edge", "restart-wave-1", "post_edge"] {
            admitted.request.mutation_phase = phase.to_owned();
            admitted.request.mutation_idempotency_key = child_mutation_idempotency_key(
                &admitted.inventory.authorization_nonce,
                phase,
                "write_canary",
            );
            validate_prepared_mutation_identity(&admitted).expect("selected core mutation phase");
            mutation_probe_root(&admitted.inventory, phase).expect("selected core probe phase");
        }
        for phase in [
            "restart-wave-0",
            "restart-wave-01",
            "restart-wave-2",
            "restart-wave-3",
            "restart-wave-4",
        ] {
            admitted.request.mutation_phase = phase.to_owned();
            admitted.request.mutation_idempotency_key = child_mutation_idempotency_key(
                &admitted.inventory.authorization_nonce,
                phase,
                "write_canary",
            );
            assert!(
                validate_prepared_mutation_identity(&admitted).is_err(),
                "{phase}"
            );
            assert!(
                mutation_probe_root(&admitted.inventory, phase).is_err(),
                "{phase}"
            );
        }
    }

    #[test]
    fn validator_process_readiness_waits_for_launcher_then_daemon() {
        let unit = b"[Service]\nExecStart=/usr/bin/python3 -c \"import os\\nos.execv(\\\"daemon\\\", [\\\"daemon\\\"])\"\n";
        let launcher = b"/usr/bin/python3\0-c\0import os\nos.execv(\"daemon\", [\"daemon\"])\0";
        let directory = tempfile::tempdir().expect("process observation fixture");
        let cmdline = directory.path().join("cmdline");
        fs::write(&cmdline, b"").expect("empty exec observation");
        let mut observations = 0;
        let mut complete_attestations = 0;
        wait_for_validator_process(Instant::now() + Duration::from_secs(2), || {
            observations += 1;
            match observations {
                1 => {
                    assert!(!validator_cmdline_is_complete(
                        &read_validator_cmdline(&cmdline, 64 * 1024)?,
                        64 * 1024,
                    )?);
                    fs::write(&cmdline, launcher)?;
                    Ok(ValidatorProcessReadiness::ExecPending)
                }
                2 => {
                    let argv = read_validator_cmdline(&cmdline, 64 * 1024)?;
                    assert!(validator_cmdline_is_complete(&argv, 64 * 1024)?);
                    validate_validator_launcher_argv(&argv, unit)?;
                    fs::write(&cmdline, b"fragment across launcher exec")?;
                    Ok(ValidatorProcessReadiness::LauncherPending)
                }
                3 => {
                    let fragment = read_validator_cmdline(&cmdline, 64 * 1024)?;
                    assert!(!fragment.ends_with(&[0]));
                    // An exact launcher-to-daemon exe change retires this raw
                    // observation before framing checks; the next poll rereads.
                    fs::write(&cmdline, b"")?;
                    Ok(ValidatorProcessReadiness::ExecPending)
                }
                4 => {
                    assert!(!validator_cmdline_is_complete(
                        &read_validator_cmdline(&cmdline, 8 * 1024)?,
                        8 * 1024,
                    )?);
                    fs::write(&cmdline, b"/service/current/bin/iroha3d_taira\0--config\0/service/current/config/config.toml\0--sora\0")?;
                    Ok(ValidatorProcessReadiness::ExecPending)
                }
                _ => {
                    let argv = read_validator_cmdline(&cmdline, 8 * 1024)?;
                    assert!(validator_cmdline_is_complete(&argv, 8 * 1024)?);
                    let arguments = argv[..argv.len() - 1]
                        .split(|byte| *byte == 0)
                        .map(|bytes| std::str::from_utf8(bytes).map(PathBuf::from))
                        .collect::<std::result::Result<Vec<_>, _>>()?;
                    validate_validator_argv(
                        &arguments,
                        Path::new("/service/current/bin/iroha3d_taira"),
                        Path::new("/service/current/config/config.toml"),
                        false,
                    )?;
                    complete_attestations += 1;
                    Ok(ValidatorProcessReadiness::Attested)
                }
            }
        })
        .expect("empty observations require a fresh complete daemon attestation");
        assert_eq!(observations, 5);
        assert_eq!(complete_attestations, 1);
    }

    #[test]
    fn validator_process_readiness_preserves_original_deadline() {
        let directory = tempfile::tempdir().expect("process deadline fixture");
        let cmdline = directory.path().join("cmdline");
        fs::write(&cmdline, b"").expect("empty exec observation");
        let mut observations = 0;
        let _ = wait_for_validator_process(Instant::now(), || {
            observations += 1;
            Ok(ValidatorProcessReadiness::Attested)
        })
        .expect_err("an elapsed deadline must not invoke the observer");
        assert_eq!(observations, 0);

        let deadline = Instant::now() + Duration::from_secs(1);
        let _ = wait_for_validator_process(deadline, || {
            observations += 1;
            // Force this observation to exhaust the original deadline instead of
            // depending on how many polling ticks the scheduler grants the test.
            std::thread::sleep(deadline.saturating_duration_since(Instant::now()));
            assert!(!validator_cmdline_is_complete(
                &read_validator_cmdline(&cmdline, 8 * 1024)?,
                8 * 1024,
            )?);
            Ok(ValidatorProcessReadiness::ExecPending)
        })
        .expect_err("an incomplete exec observation cannot extend the existing action deadline");
        assert_eq!(observations, 1);
        let _ = wait_for_validator_process(deadline, || {
            observations += 1;
            Ok(ValidatorProcessReadiness::Attested)
        })
        .expect_err("reentry cannot renew the elapsed deadline or perform more work");
        assert_eq!(observations, 1);
        // Start, Restart and rollback-start submit their durable manager operation
        // before this observer-only loop; pending observations cannot resubmit it.
    }

    #[test]
    fn validator_process_readiness_rejects_changed_launcher_immediately() {
        let unit = b"[Service]\nExecStart=/usr/bin/python3 -c \"signed_command()\"\n";
        let directory = tempfile::tempdir().expect("invalid process observation fixture");
        let cmdline = directory.path().join("cmdline");
        for maximum in [8 * 1024, 64 * 1024] {
            for (argv, expected_error) in [
                (
                    b"nonempty without NUL".to_vec(),
                    "validator MainPID cmdline is missing its terminal NUL",
                ),
                (
                    vec![0; maximum + 1],
                    "validator MainPID cmdline exceeds the exact byte bound",
                ),
            ] {
                fs::write(&cmdline, argv).expect("invalid bounded cmdline");
                let mut observations = 0;
                let error =
                    wait_for_validator_process(Instant::now() + Duration::from_secs(1), || {
                        observations += 1;
                        let argv = read_validator_cmdline(&cmdline, maximum)?;
                        validator_cmdline_is_complete(&argv, maximum)?;
                        Ok(ValidatorProcessReadiness::ExecPending)
                    })
                    .expect_err("malformed nonempty or oversized argv must never become pending");
                assert_eq!(error.to_string(), expected_error);
                assert_eq!(observations, 1);
            }
        }
        let mut observations = 0;
        let _ = wait_for_validator_process(Instant::now() + Duration::from_secs(1), || {
            observations += 1;
            validate_validator_launcher_argv(b"/usr/bin/python3\0-c\0changed_command()\0", unit)?;
            Ok(ValidatorProcessReadiness::LauncherPending)
        })
        .expect_err("a different Python command must fail without polling");
        assert_eq!(observations, 1);
        for argv in [
            b"/usr/bin/python3\0script.py\0".as_slice(),
            b"/usr/bin/python3\0-c\0\0".as_slice(),
            b"/tmp/python3\0-c\0signed_command()\0".as_slice(),
            b"/usr/bin/python3\0-c\0signed_command()\0extra\0".as_slice(),
        ] {
            assert!(validate_validator_launcher_argv(argv, unit).is_err());
        }
    }

